mapper.select:
SELECT m.SECID secid, f.FINPROD_ABBR finprodAbbr, m.VALUE_SOURCE, m.CDATE cdate, m.MDPRICE mdprice, m.MCPRICE mcprice, m.MINT mint, m.MYIELD*100 myield, m.M_MDURATION mMduration, m.M_CNVXTY mCnvxty, m.ISSUE_MARKET_NUM issueMarketNum, m.CREDIT_TYPE creditType FROM MST_CREDIT_MARKET_INFO m LEFT JOIN FIN_PRODUCT f ON f.FINPROD_ID=m.SECID LEFT JOIN INTERF_CREDITINFO i ON i.SECID = m.SECID
AND (m.SECID IN
#{item}
)
AND m.VALUE_SOURCE = #{valueSource}
AND m.cdate >= TO_DATE(#{cdateStart},'YYYY-MM-DD')
AND m.cdate <= TO_DATE(#{cdateEnd},'YYYY-MM-DD')
ORDER BY m.SECID

